  let slow = head
  let fast = head
  while (fast !== null && fast.next !== null) {
    slow = slow.next
    fast = fast.next.next
    if (slow === fast) {
      let probe = head
      while (probe !== slow) {
        probe = probe.next
        slow = slow.next
      }
      return probe
    }
  }
  return null
}

