def find_entry(head):
    slow = fast = head
    while fast is not None and fast["next"] is not None:
        slow = slow["next"]
        fast = fast["next"]["next"]
        if slow is fast:
            probe = head
            while probe is not slow:
                probe = probe["next"]
                slow = slow["next"]
            return probe
    return None


